class Solution {
  public int[] pathExistenceQueries(int n, int[] nums, int maxDiff, int[][] queries) {
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    java.util.Arrays.sort(order, (a, b) -> Integer.compare(nums[a], nums[b]));
    int[] pos = new int[n], val = new int[n];
    for (int i = 0; i < n; i++) {
      pos[order[i]] = i;
      val[i] = nums[order[i]];
    }
    int LOG = 1;
    while ((1 << LOG) < n) LOG++;
    int[][] up = new int[LOG + 1][n];
    for (int i = 0, j = 0; i < n; i++) {
      if (j < i) j = i;
      while (j + 1 < n && val[j + 1] - val[i] <= maxDiff) j++;
      up[0][i] = j;
    }
    for (int l = 1; l <= LOG; l++) for (int i = 0; i < n; i++) up[l][i] = up[l - 1][up[l - 1][i]];
    int[] ans = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int a = pos[queries[qi][0]], b = pos[queries[qi][1]];
      if (a > b) {
        int t = a;
        a = b;
        b = t;
      }
      if (a == b) {
        ans[qi] = 0;
        continue;
      }
      int cur = a, steps = 0;
      for (int l = LOG; l >= 0; l--) {
        if (up[l][cur] < b) {
          cur = up[l][cur];
          steps += 1 << l;
        }
      }
      ans[qi] = up[0][cur] >= b ? steps + 1 : -1;
    }
    return ans;
  }
}
